package com.orderflow;

import org.springframework.stereotype.Service;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.annotation.Transactional;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneOffset;
import java.util.*;
import static com.orderflow.Contracts.*;

@Service
public class OperationsService {
 private final JdbcTemplate db;
 public OperationsService(JdbcTemplate db){this.db=db;}
 static String id(){return UUID.randomUUID().toString();}
 static String now(){return Instant.now().toString();}
 static long number(Map<String,Object> row,String key){return ((Number)row.get(key)).longValue();}
 private Map<String,Object> one(String sql,Object...args){var rows=db.queryForList(sql,args);if(rows.isEmpty())throw new BusinessException(404,"Record not found");return rows.getFirst();}
 private void event(String order,String action,String detail){db.update("INSERT INTO activity VALUES(?,?,?,?,?)",id(),order,action,detail.length()>1000?detail.substring(0,1000):detail,now());}
 private String hash(String value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
 private void lockKey(String scope,String key){if(key==null||!key.matches("[A-Za-z0-9._:-]{8,100}"))throw new BusinessException(400,"Provide an Idempotency-Key of 8–100 letters, numbers, dots, colons or hyphens.");int bucket=Math.floorMod((scope+":"+key).hashCode(),64);one("SELECT bucket FROM operation_locks WHERE bucket=? FOR UPDATE",bucket);}
 private String replay(String scope,String key,String fingerprint){var rows=db.queryForList("SELECT * FROM idempotency_keys WHERE scope=? AND key_value=?",scope,key);if(rows.isEmpty())return null;if(!rows.getFirst().get("fingerprint").equals(hash(fingerprint)))throw new BusinessException(409,"This idempotency key was already used for different input.");return (String)rows.getFirst().get("resource_id");}
 private void remember(String scope,String key,String fingerprint,String resource){db.update("INSERT INTO idempotency_keys VALUES(?,?,?,?,?)",scope,key,hash(fingerprint),resource,now());}
 private Map<String,Object> lockStock(String warehouse,String product){return one("SELECT * FROM inventory WHERE warehouse_id=? AND product_id=? FOR UPDATE",warehouse,product);}
 private Map<String,Object> lockOrder(String order){return one("SELECT * FROM orders WHERE id=? FOR UPDATE",order);}
 private void movement(String warehouse,String product,String order,String kind,int onHand,int reserved,String reason){db.update("INSERT INTO stock_movements VALUES(?,?,?,?,?,?,?,?,?)",id(),warehouse,product,order,kind,onHand,reserved,reason,now());}

 @Transactional(readOnly=true) public List<Map<String,Object>> products(){return db.queryForList("SELECT * FROM products ORDER BY name");}
 @Transactional(readOnly=true) public List<Map<String,Object>> warehouses(){return db.queryForList("SELECT * FROM warehouses ORDER BY name");}
 @Transactional(readOnly=true) public List<Map<String,Object>> inventory(){return db.queryForList("SELECT i.*,i.on_hand-i.reserved available,p.sku,p.name,p.category,p.price_cents,w.name warehouse_name,w.location FROM inventory i JOIN products p ON i.product_id=p.id JOIN warehouses w ON i.warehouse_id=w.id ORDER BY w.name,p.name");}
 @Transactional(readOnly=true) public List<Map<String,Object>> orders(){return db.queryForList("SELECT o.*,w.name warehouse_name,(SELECT SUM(l.quantity) FROM order_lines l WHERE l.order_id=o.id) units FROM orders o JOIN warehouses w ON o.warehouse_id=w.id ORDER BY o.created_at DESC");}
 @Transactional(readOnly=true) public Map<String,Object> order(String id){var row=new LinkedHashMap<>(one("SELECT o.*,w.name warehouse_name FROM orders o JOIN warehouses w ON o.warehouse_id=w.id WHERE o.id=?",id));row.put("lines",db.queryForList("SELECT * FROM order_lines WHERE order_id=? ORDER BY sku",id));row.put("payments",db.queryForList("SELECT * FROM payment_events WHERE order_id=? ORDER BY created_at",id));row.put("returns",db.queryForList("SELECT * FROM returns WHERE order_id=? ORDER BY created_at",id));row.put("timeline",db.queryForList("SELECT * FROM activity WHERE order_id=? ORDER BY created_at",id));return row;}
 @Transactional(readOnly=true) public List<Map<String,Object>> activity(){return db.queryForList("SELECT a.*,o.reference FROM activity a LEFT JOIN orders o ON a.order_id=o.id ORDER BY a.created_at DESC LIMIT 100");}
 @Transactional(readOnly=true) public List<Map<String,Object>> movements(){return db.queryForList("SELECT m.*,p.name,p.sku,w.name warehouse_name,o.reference FROM stock_movements m JOIN products p ON m.product_id=p.id JOIN warehouses w ON m.warehouse_id=w.id LEFT JOIN orders o ON m.order_id=o.id ORDER BY m.created_at DESC LIMIT 200");}
 @Transactional(readOnly=true) public Map<String,Object> overview(){return Map.of("orders",one("SELECT COUNT(*) total,COALESCE(SUM(CASE WHEN status='RESERVED' THEN 1 ELSE 0 END),0) awaiting_payment,COALESCE(SUM(CASE WHEN status='PAID' THEN 1 ELSE 0 END),0) ready_to_ship,COALESCE(SUM(CASE WHEN status IN ('PAID','FULFILLED','PARTIALLY_RETURNED','RETURNED') THEN total_cents-refunded_cents ELSE 0 END),0) net_paid_cents,COALESCE(SUM(refunded_cents),0) refunded_cents FROM orders"),"stock",one("SELECT COALESCE(SUM(on_hand),0) on_hand,COALESCE(SUM(reserved),0) reserved,COALESCE(SUM(on_hand-reserved),0) available,COALESCE(SUM(CASE WHEN on_hand-reserved<5 THEN 1 ELSE 0 END),0) low_stock_positions FROM inventory"),"products",one("SELECT COUNT(*) total FROM products").get("total"));}

 @Transactional public Map<String,Object> createProduct(ProductInput input){one("SELECT bucket FROM operation_locks WHERE bucket=0 FOR UPDATE");String product=id();db.update("INSERT INTO products VALUES(?,?,?,?,?,?)",product,input.sku().trim().toUpperCase(Locale.ROOT),input.name().trim(),input.category().trim(),input.priceCents(),now());for(var w:warehouses())db.update("INSERT INTO inventory VALUES(?,?,0,0)",w.get("id"),product);event(null,"product.created",input.sku()+" · "+input.name());return one("SELECT * FROM products WHERE id=?",product);}
 @Transactional public Map<String,Object> createWarehouse(WarehouseInput input){one("SELECT bucket FROM operation_locks WHERE bucket=0 FOR UPDATE");String warehouse=id();db.update("INSERT INTO warehouses VALUES(?,?,?)",warehouse,input.name().trim(),input.location().trim());for(var p:products())db.update("INSERT INTO inventory VALUES(?,?,0,0)",warehouse,p.get("id"));event(null,"warehouse.created",input.name());return one("SELECT * FROM warehouses WHERE id=?",warehouse);}
 @Transactional public Map<String,Object> receive(StockInput input,String key){String scope="stock.receive",fingerprint=input.warehouseId()+":"+input.productId()+":"+input.quantity()+":"+input.reason().trim();lockKey(scope,key);String previous=replay(scope,key,fingerprint);if(previous!=null)return one("SELECT * FROM stock_movements WHERE id=?",previous);var stock=lockStock(input.warehouseId(),input.productId());if(number(stock,"on_hand")+input.quantity()>10000000)throw new BusinessException(400,"Stock position exceeds the supported limit.");db.update("UPDATE inventory SET on_hand=on_hand+? WHERE warehouse_id=? AND product_id=?",input.quantity(),input.warehouseId(),input.productId());String movement=id();db.update("INSERT INTO stock_movements VALUES(?,?,?,?,?,?,?,?,?)",movement,input.warehouseId(),input.productId(),null,"RECEIPT",input.quantity(),0,input.reason().trim(),now());remember(scope,key,fingerprint,movement);event(null,"stock.received",input.quantity()+" units received · "+input.reason().trim());return one("SELECT * FROM stock_movements WHERE id=?",movement);}

 @Transactional public Map<String,Object> createOrder(OrderInput input,String key){
  String scope="order.create";var sorted=input.lines().stream().sorted(Comparator.comparing(LineInput::productId)).toList();if(sorted.stream().map(LineInput::productId).distinct().count()!=sorted.size())throw new BusinessException(400,"Each product can appear only once in an order.");
  String fingerprint=input.customer().trim()+"|"+input.warehouseId()+"|"+sorted.stream().map(l->l.productId()+":"+l.quantity()).toList();lockKey(scope,key);String previous=replay(scope,key,fingerprint);if(previous!=null)return order(previous);
  one("SELECT id FROM warehouses WHERE id=?",input.warehouseId());long total=0;var snapshots=new ArrayList<Map<String,Object>>();
  for(var line:sorted){var stock=lockStock(input.warehouseId(),line.productId());var product=one("SELECT * FROM products WHERE id=?",line.productId());if(number(stock,"on_hand")-number(stock,"reserved")<line.quantity())throw new BusinessException(409,"Insufficient available stock for "+product.get("name")+". No items were reserved.");total=Math.addExact(total,Math.multiplyExact(number(product,"price_cents"),line.quantity()));snapshots.add(product);}
  String orderId=id(),reference="OF-"+LocalDate.now(ZoneOffset.UTC).toString().replace("-","").substring(2)+"-"+orderId.substring(0,6).toUpperCase(Locale.ROOT),date=now();db.update("INSERT INTO orders VALUES(?,?,?,?,?,?,0,?,?)",orderId,reference,input.customer().trim(),input.warehouseId(),"RESERVED",total,date,date);
  for(int i=0;i<sorted.size();i++){var line=sorted.get(i);var product=snapshots.get(i);db.update("INSERT INTO order_lines VALUES(?,?,?,?,?,?,?,0)",id(),orderId,line.productId(),product.get("sku"),product.get("name"),product.get("price_cents"),line.quantity());db.update("UPDATE inventory SET reserved=reserved+? WHERE warehouse_id=? AND product_id=?",line.quantity(),input.warehouseId(),line.productId());movement(input.warehouseId(),line.productId(),orderId,"RESERVE",0,line.quantity(),"Order reservation");}
  remember(scope,key,fingerprint,orderId);event(orderId,"order.reserved","Stock reserved; awaiting simulated payment");return order(orderId);
 }
 @Transactional public Map<String,Object> cancel(String orderId){var order=lockOrder(orderId);String status=(String)order.get("status");if(status.equals("CANCELLED"))return order(orderId);if(!status.equals("RESERVED"))throw new BusinessException(409,"Only unpaid reserved orders can be cancelled.");String warehouse=(String)order.get("warehouse_id");var lines=db.queryForList("SELECT * FROM order_lines WHERE order_id=? ORDER BY product_id",orderId);for(var line:lines){String product=(String)line.get("product_id");int quantity=(int)number(line,"quantity");lockStock(warehouse,product);db.update("UPDATE inventory SET reserved=reserved-? WHERE warehouse_id=? AND product_id=?",quantity,warehouse,product);movement(warehouse,product,orderId,"RELEASE",0,-quantity,"Cancelled unpaid order");}db.update("UPDATE orders SET status='CANCELLED',updated_at=? WHERE id=?",now(),orderId);event(orderId,"order.cancelled","Reservation released");return order(orderId);}

 @Transactional public Map<String,Object> payment(PaymentInput input){
  lockKey("payment",input.eventId());var existing=db.queryForList("SELECT * FROM payment_events WHERE event_id=?",input.eventId());if(!existing.isEmpty()){var e=existing.getFirst();if(!e.get("order_id").equals(input.orderId())||number(e,"amount_cents")!=input.amountCents()||!e.get("outcome").equals(input.outcome()))throw new BusinessException(409,"Payment event ID already belongs to different input.");return Map.of("event",e,"order",order(input.orderId()),"replayed",true);}
  var order=lockOrder(input.orderId());if(number(order,"total_cents")!=input.amountCents())throw new BusinessException(409,"Payment amount does not match the order total.");String status=(String)order.get("status"),effect;
  if(status.equals("CANCELLED"))effect="IGNORED_CANCELLED";
  else if(!status.equals("RESERVED"))effect="ALREADY_CONFIRMED";
  else if(input.outcome().equals("FAILED"))effect="PAYMENT_FAILED";
  else{effect="CONFIRMED";db.update("UPDATE orders SET status='PAID',updated_at=? WHERE id=?",now(),input.orderId());}
  db.update("INSERT INTO payment_events VALUES(?,?,?,?,?,?)",input.eventId(),input.orderId(),input.amountCents(),input.outcome(),now(),effect);event(input.orderId(),"payment."+effect.toLowerCase(Locale.ROOT),"Simulator event "+input.eventId());return Map.of("event",one("SELECT * FROM payment_events WHERE event_id=?",input.eventId()),"order",order(input.orderId()),"replayed",false);
 }
 @Transactional public Map<String,Object> fulfill(String orderId){var order=lockOrder(orderId);String status=(String)order.get("status");if(status.equals("FULFILLED"))return order(orderId);if(!status.equals("PAID"))throw new BusinessException(409,"Confirm payment before fulfilling an order.");String warehouse=(String)order.get("warehouse_id");for(var line:db.queryForList("SELECT * FROM order_lines WHERE order_id=? ORDER BY product_id",orderId)){String product=(String)line.get("product_id");int quantity=(int)number(line,"quantity");lockStock(warehouse,product);db.update("UPDATE inventory SET on_hand=on_hand-?,reserved=reserved-? WHERE warehouse_id=? AND product_id=?",quantity,quantity,warehouse,product);movement(warehouse,product,orderId,"SHIP",-quantity,-quantity,"Fulfilled shipment");}db.update("UPDATE orders SET status='FULFILLED',updated_at=? WHERE id=?",now(),orderId);event(orderId,"order.fulfilled","Shipment recorded; physical and reserved stock reduced");return order(orderId);}
 @Transactional public Map<String,Object> returnOrder(String orderId,ReturnInput input,String key){
  String scope="order.return:"+orderId;var sorted=input.lines().stream().sorted(Comparator.comparing(ReturnLineInput::lineId)).toList();if(sorted.stream().map(ReturnLineInput::lineId).distinct().count()!=sorted.size())throw new BusinessException(400,"Each order line can appear only once in a return.");String fingerprint=input.reason().trim()+"|"+sorted;lockKey(scope,key);String previous=replay(scope,key,fingerprint);if(previous!=null)return order(orderId);
  var order=lockOrder(orderId);if(!Set.of("FULFILLED","PARTIALLY_RETURNED").contains(order.get("status")))throw new BusinessException(409,"Returns require a fulfilled order with remaining items.");var lines=db.queryForList("SELECT * FROM order_lines WHERE order_id=? ORDER BY product_id",orderId);var quantities=new HashMap<String,Integer>();for(var request:sorted){var line=lines.stream().filter(l->l.get("id").equals(request.lineId())).findFirst().orElseThrow(()->new BusinessException(400,"Return line does not belong to this order."));if(request.quantity()>number(line,"quantity")-number(line,"returned"))throw new BusinessException(409,"Return quantity exceeds the remaining shipped quantity.");quantities.put(request.lineId(),request.quantity());}
  long refund=0;String returnId=id(),warehouse=(String)order.get("warehouse_id");for(var line:lines){Integer quantity=quantities.get(line.get("id"));if(quantity!=null)refund=Math.addExact(refund,Math.multiplyExact(quantity,number(line,"unit_price_cents")));}
  db.update("INSERT INTO returns VALUES(?,?,?,?,?)",returnId,orderId,refund,input.reason().trim(),now());
  for(var line:lines){Integer quantity=quantities.get(line.get("id"));if(quantity==null)continue;String product=(String)line.get("product_id");lockStock(warehouse,product);db.update("UPDATE inventory SET on_hand=on_hand+? WHERE warehouse_id=? AND product_id=?",quantity,warehouse,product);db.update("UPDATE order_lines SET returned=returned+? WHERE id=?",quantity,line.get("id"));db.update("INSERT INTO return_lines VALUES(?,?,?)",returnId,line.get("id"),quantity);movement(warehouse,product,orderId,"RETURN",quantity,0,input.reason().trim());}
  long refunded=number(order,"refunded_cents")+refund;String next=refunded==number(order,"total_cents")?"RETURNED":"PARTIALLY_RETURNED";db.update("UPDATE orders SET status=?,refunded_cents=?,updated_at=? WHERE id=?",next,refunded,now(),orderId);remember(scope,key,fingerprint,returnId);event(orderId,"order.returned","Simulated refund of "+refund+" cents; returned units restocked");return order(orderId);
 }
}
